INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(63394872, 'Senet Switch', '位置移动', 'ポジションチェンジ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，以自己的主要怪兽区域1只怪兽为对象，指定那相邻的没有使用的怪兽区域1处才能发动。那只自己怪兽的位置向相邻的指定的区域移动。'),
(76232340, 'Sengenjin', '仟年原人', '千年原人', 'Normal Monster', 'Beast-Warrior', 'EARTH', 8, 2750, 2500, '无论何时都靠力量硬干到底，拥有千年宝物的原始人。'),
(38775407, 'Sengenjin Wakes from a Millennium', '觉醒于仟年长眠中的原人', '千年の眠りから覚めし原人', 'Effect Monster', 'Beast-Warrior', 'EARTH', 8, 2750, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合才能发动。这张卡当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：这张卡是当作永续魔法卡使用的场合，支付2000基本分或把手卡1张「千年十字」给对方观看才能发动。这张卡特殊召唤。那之后，可以从卡组把1只「千年」怪兽加入手卡。 ③：这张卡只要在怪兽区域存在，不会被怪兽的效果破坏。'),
(87483942, 'Senior Silver Ninja', '素银忍者', '渋い忍者', 'Effect Monster', 'Warrior', 'EARTH', 6, 2300, 2200, '这张卡反转时，可以从自己的手卡·墓地把「素银忍者」以外的名字带有「忍者」的怪兽任意数量里侧守备表示特殊召唤。「素银忍者」在场上只能有1只表侧表示存在。'),
(23401839, 'Senju of the Thousand Hands', '千手之神', 'センジュ・ゴッド', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 1000, '①：这张卡召唤·反转召唤时才能发动。从卡组把1只仪式怪兽加入手卡。'),
(62503746, 'Senko the Skybolt Star', '天雷星 闪光', '天雷星センコウ', 'Effect Monster', 'Warrior', 'LIGHT', 7, 2400, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有地属性怪兽召唤·特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：把墓地的这张卡除外，以自己场上1只5星以上的战士族怪兽和对方场上1只攻击表示怪兽为对象才能发动。那只自己怪兽的攻击力下降1500，那只对方怪兽破坏。'),
(60391791, 'Senri Eye', '千里眼', '千里眼', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，在自己的准备阶段支付100基本分，就可以确认对方卡组最上面的1张卡，之后将其放回。对方不能确认这张卡。'),
(40771118, 'Sentence of Doom', '死之宣告', '死の宣告', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己墓地的怪兽以及除外的自己怪兽之中以最多有自己场上的「通灵盘」以及「死之信息」卡数量的恶魔族怪兽为对象才能发动。那些怪兽加入手卡。 ②：把魔法与陷阱区域的这张卡送去墓地才能发动。从自己的手卡·卡组·墓地选1张「死之信息」卡当作「通灵盘」的效果在自己的魔法与陷阱区域出现。'),
(85448931, 'Sentinel of the Seas', '守海战士', '海を守る戦士', 'Normal Monster', 'Aqua', 'WATER', 4, 1300, 1000, '彻底的攻击玷污大海的家伙、人鱼战士。'),
(86111442, 'Sentinel of the Tistina', '提斯蒂娜的哨兵', 'ティスティナの歩哨', 'Effect Monster', 'Aqua', 'WIND', 3, 1200, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己场上有光属性「提斯蒂娜」怪兽存在的场合才能发动。这张卡特殊召唤。 ②：以自己场上1只「提斯蒂娜」怪兽或1张里侧表示卡为对象才能发动。那张卡破坏。那之后，从卡组把1张「提斯蒂娜」卡加入手卡。'),
(57354389, 'Sentry Soldier of Stone', '岩石番兵', '岩石の番兵', 'Effect Monster', 'Rock', 'EARTH', 3, 1300, 2000, '这个卡名的效果1回合只能使用1次。 ①：这张卡在墓地存在，自己场上的怪兽只有岩石族怪兽的场合才能发动。这张卡特殊召唤。'),
(8967776, 'Sephylon, the Ultimate Timelord', '究极时械神 赛菲隆', '究極時械神セフィロン', 'Effect Monster', 'Fairy', 'LIGHT', 10, 4000, 4000, '这张卡不能通常召唤。自己墓地有怪兽10只以上存在的场合才能特殊召唤。1回合1次，可以把1只8星以上的天使族怪兽从自己的手卡·墓地特殊召唤。这个效果特殊召唤的怪兽的效果无效化，攻击力变成4000。'),
(91140491, 'Seraphim Papillion', '炽天蝶', '熾天蝶', 'Link Monster', 'Insect', 'WIND', NULL, 2100, NULL, '卡名不同的怪兽2只以上 这个卡名的①③的效果1回合只能有1次使用其中任意1个。 ①：这张卡连接召唤成功的场合发动。作为这张卡的连接素材的昆虫族怪兽数量的指示物给这张卡放置。 ②：这张卡的攻击力上升这张卡的指示物数量×200。 ③：把这张卡1个指示物取除才能发动。从自己墓地选1只4星以下的昆虫族怪兽守备表示特殊召唤。这个效果在对方回合也能发动。'),
(42029847, 'Serenade the Melodious Diva', '幻奏音女 塞雷娜', '幻奏の音女セレナ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 400, 1900, '①：天使族怪兽上级召唤的场合，这张卡可以作为2只的数量解放。 ②：这张卡特殊召唤成功的回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「幻奏」怪兽召唤。'),
(9213491, 'Serene Psychic Girl', '静寂的念力女孩', '静寂のサイコガール', 'Tuner Monster', 'Psychic', 'EARTH', 2, 500, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。选自己1张手卡除外，除「静寂的念力少女」外的1只4星以下的念动力族怪兽从卡组特殊召唤。这个回合，自己不是念动力族怪兽不能从额外卡组特殊召唤。 ②：以最多有自己场上的念动力族怪兽数量的场上的表侧表示怪兽为对象才能发动。那些怪兽的等级直到回合结束时上升1星。'),
(5848934, 'Serene Psychic Sorceress', '静寂的念力女术士', '静寂のサイコソーサレス', 'Synchro Monster', 'Psychic', 'EARTH', 6, 2400, 2200, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合，支付1000基本分才能发动。自己的卡组·墓地·除外状态的1张「瞬间移动」通常·速攻魔法卡在自己场上盖放。 ②：同调召唤的这张卡被送去墓地的场合，以对方场上1张卡为对象才能发动（念动力族的融合·同调怪兽的其中任意种在自己场上存在的场合，这个效果的对象可以变成2张）。那张卡回到手卡。'),
(98358303, 'Serene Psychic Witch', '静寂的念力女巫', '静寂のサイコウィッチ', 'Effect Monster', 'Psychic', 'EARTH', 3, 1400, 1200, '①：场上的这张卡被破坏送去墓地时才能发动。从卡组把1只攻击力2000以下的念动力族怪兽除外。 ②：这张卡的①的效果把怪兽除外的场合，下次的准备阶段在墓地发动。那只除外状态的怪兽特殊召唤。'),
(43359262, 'Sergeant Electro', '电力军曹', 'エレクトロ軍曹', 'Effect Monster', 'Machine', 'FIRE', 4, 1600, 1300, '①：1回合1次，以对方的魔法与陷阱区域盖放的1张卡为对象才能发动。这张卡得到以下效果。 ●只要这张卡在怪兽区域存在，作为对象的盖放的卡不能发动。'),
(49398568, 'Serial Spell', '连续魔法', '連続魔法', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己发动通常魔法时才能发动。手卡全部丢弃去墓地。这张卡的效果，变成和那张通常魔法的效果相同。'),
(82742611, 'Serpent Marauder', '恶魔蛇', 'デビル・スネーク', 'Normal Monster', 'Reptile', 'EARTH', 2, 700, 600, '独眼蛇。吐出冷气冰封对方。'),
(66516792, 'Serpent Night Dragon', '邪恶骑士龙', 'エビルナイト・ドラゴン', 'Normal Monster', 'Dragon', 'DARK', 7, 2350, 2400, '宿于邪恶骑士心中之龙的实体化形。'),
(19451302, 'Serpent Suppression', '蛇绞', 'スネーク・チョーク', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方场上表侧攻击表示存在的攻击力是0的怪兽不会被和名字带有「爬虫妖」的怪兽的战斗破坏。'),
(71829750, 'Serpentine Princess', '那迦', 'ナーガ', 'Effect Monster', 'Reptile', 'WATER', 4, 1400, 2000, '①：表侧表示的这张卡从场上回到卡组的场合发动。从卡组把1只3星以下的怪兽特殊召唤。'),
(2792265, 'Servant of Catabolism', '异形的从者', '異形の従者', 'Effect Monster', 'Aqua', 'LIGHT', 3, 700, 500, '这张卡可以直接攻击对方玩家。'),
(92559258, 'Servant of Endymion', '恩底弥翁之侍从', 'サーヴァント・オブ・エンディミオン', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 3, 900, 1500, '自己对「恩底弥翁的仆从」1回合只能有1次特殊召唤。 ①：有魔力指示物放置的这张卡可以直接攻击。 ②：对方回合1次，丢弃1张手卡才能发动。给这张卡以及自己场上的可以放置魔力指示物的卡全部各放置1个魔力指示物。 ③：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。那之后，这张卡放置过的数量的魔力指示物给这张卡放置。'),
(300103004, 'Servants of the Fallen King', NULL, NULL, 'Skill Card', 'Bonz', NULL, NULL, NULL, NULL, NULL),
(36400569, 'Service Puppet Play', '傀儡游仪－饭杀傀偶', '傀儡遊儀－サービスト・パペット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以最多有自己场上的「机关傀儡」超量怪兽数量的对方场上的怪兽为对象才能发动。那些怪兽的控制权直到结束阶段得到。 ②：自己场上有「机关傀儡」超量怪兽存在的场合，把这个回合没有送去墓地的这张卡从墓地除外，以自己或对方的墓地1只超量怪兽为对象才能发动。那只怪兽在自己或对方的场上守备表示特殊召唤。'),
(82466274, 'Serziel, Watcher of the Evil Eye', '咒眼之死徒 沙利叶', '呪眼の死徒 サリエル', 'Effect Monster', 'Fiend', 'DARK', 4, 1600, 1400, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。从卡组把「咒眼之死徒 沙利叶」以外的1张「咒眼」卡加入手卡。 ②：这张卡有「太阴之咒眼」装备的场合，以对方场上1只特殊召唤的怪兽为对象才能发动。那只怪兽破坏。这个效果在对方回合也能发动。 ③：这张卡的②的效果发动的场合，下次的准备阶段发动。选自己场上1张卡破坏。'),
(73468603, 'Set Rotation', '布景旋转', '盆回し', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从卡组选2张卡名不同的场地魔法卡，那之内的1张在自己场上盖放，另1张在对方场上盖放。只要这个效果盖放的卡的其中任意张在场地区域盖放中，双方不能把其他的场地魔法卡发动·盖放。'),
(300302072, 'Setting Sun', NULL, NULL, 'Skill Card', 'Amnael', NULL, NULL, NULL, NULL, NULL),
(19590644, 'Setuppercut', '布局上钩拳', 'セットアッパー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己怪兽被战斗破坏时才能发动。把持有那只怪兽的攻击力以下的攻击力的1只怪兽从手卡·卡组里侧守备表示特殊召唤。'),
(95034141, 'Seven Cities of the Golden Land', '黄金乡的七摩天', '黄金郷の七摩天', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从自己的手卡·场上把融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。那个时候，融合素材怪兽必须全部是不死族怪兽。 ②：卡的效果让不死族怪兽特殊召唤的场合，以魔法与陷阱区域盖放的1张卡为对象才能发动。盖放的那张卡在这个回合不能发动。'),
(65114115, 'Seven Stars Slash - Army Annihilator Hagun', '七星天流拔刀术－“破军”', '七星天流抜刀術－「破軍」', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只表侧表示怪兽为对象才能发动。和那只怪兽是卡名不同并是种族相同的1只7星怪兽当作攻击力上升700的装备魔法卡使用从手卡·卡组给作为对象的怪兽装备。这个效果装备的卡在结束阶段回到手卡。 ②：这张卡在墓地存在的状态，等级·阶级是8以上的对方怪兽被战斗破坏时才能发动。这张卡加入手卡。'),
(43366227, 'Seven Swords Warrior', '七剑战士', 'セブン・ソード・ウォリアー', 'Synchro Monster', 'Warrior', 'EARTH', 7, 2300, 1800, '调整＋调整以外的怪兽1只以上 1回合1次，这张卡被装备卡装备时，给与对方基本分800分伤害。此外，1回合1次，可以把这张卡装备的1张装备卡送去墓地。这张卡装备的装备卡送去墓地时，可以选择对方场上表侧表示存在的1只怪兽破坏。'),
(3819470, 'Seven Tools of the Bandit', '盗贼的七道具', '盗賊の七つ道具', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：陷阱卡发动时，支付1000基本分才能发动。那个发动无效并破坏。'),
(23153227, 'Seventh Ascension', '七皇升格', '七皇昇格', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组选以下的卡之内任意1张加入手卡或在卡组最上面放置。 ●「七皇升格」以外的「七皇」魔法·陷阱卡 ●「异晶人的」魔法·陷阱卡 ●「升阶魔法」速攻魔法卡 ②：从额外卡组特殊召唤的怪兽在对方场上存在的场合，把墓地的这张卡除外，从手卡把1张「升阶魔法」魔法卡送去墓地才能发动。这个效果变成和那张魔法卡发动时的效果相同。'),
(60158866, 'Seventh Eternity', '不朽的七皇', '不朽の七皇', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：可以以自己场上1只「No.101」～「No.107」其中任意种的「No.」超量怪兽或者有那怪兽在作为超量素材中的超量怪兽为对象，从以下效果选择1个发动。 ●选持有作为对象的怪兽的攻击力以下的攻击力的对方场上1只怪兽，那个效果直到回合结束时无效。 ●作为对象的怪兽的超量素材全部取除。那之后，可以从自己墓地选1只「No.」超量怪兽特殊召唤。'),
(83293635, 'Seventh Force', '七皇觉醒', '七皇覚醒', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：战斗阶段，怪兽被战斗·效果破坏的场合，以自己墓地1只「No.」超量怪兽为对象才能发动。种族和那只怪兽相同而阶级高1阶的1只「混沌No.」怪兽从额外卡组特殊召唤，把作为对象的怪兽作为那超量素材。这个效果把「混沌No.101」～「混沌No.107」怪兽的其中任意种特殊召唤的场合，可以再把除「七皇觉醒」外的「七皇」魔法·陷阱卡、「异晶人的」魔法·陷阱卡、「升阶魔法」速攻魔法卡的其中1张从卡组加入手卡。'),
(7477101, 'Seventh Tachyon', '时空之七皇', '時空の七皇', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把额外卡组1只「No.101」～「No.107」其中任意种的「No.」超量怪兽给对方观看才能发动。种族或属性和给人观看的怪兽相同而持有和那只怪兽的阶级相同数值的等级的1只怪兽从卡组加入手卡。那之后，选自己1张手卡回到卡组最上面。这张卡的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。'),
(99162753, 'Sextet Summon', '六界召唤', 'セクステット・サモン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·墓地以及自己场上的表侧表示怪兽之中选原本种族相同的怪兽6种类（仪式·融合·同调·超量·灵摆·连接）各1只除外。那之后，原本种族和除外的怪兽相同的1只怪兽从卡组·额外卡组特殊召唤。'),
(3717252, 'Shaddoll Beast', '影依・野兽', 'シャドール・ビースト', 'Flip Effect Monster', 'Spellcaster', 'DARK', 5, 2200, 1700, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合才能发动。自己抽2张。那之后，选自己1张手卡丢弃。 ②：这张卡被效果送去墓地的场合才能发动。自己抽1张。'),
(86938484, 'Shaddoll Construct', '影依・拿非利', 'シャドール・ネフィリム', 'Link Monster', 'Fairy', 'LIGHT', NULL, 1200, NULL, '反转怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。自己的手卡·场上的怪兽作为融合素材，把1只「影依」融合怪兽融合召唤。 ②：这张卡在墓地存在的场合才能发动。从自己的手卡·场上（表侧表示）把1张「影依」卡送去墓地，这张卡特殊召唤。'),
(4904633, 'Shaddoll Core', '影依的原核', '影依の原核', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（魔法师族·暗·9星·攻1450/守1950）在怪兽区域特殊召唤。把这个效果特殊召唤的这张卡作为「影依」融合怪兽的融合素材的场合，可以作为那张卡记述的属性的融合素材怪兽的代替。这张卡也当作陷阱卡使用。 ②：这张卡被效果送去墓地的场合，以「影依的原核」以外的自己墓地1张「影依」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(77723643, 'Shaddoll Dragon', '影依・龙', 'シャドール・ドラゴン', 'Flip Effect Monster', 'Spellcaster', 'DARK', 4, 1900, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合，以对方场上1张卡为对象才能发动。那张卡回到手卡。 ②：这张卡被效果送去墓地的场合，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(37445295, 'Shaddoll Falco', '影依・隼', 'シャドール・ファルコン', 'Flip Tuner Effect Monster', 'Spellcaster', 'DARK', 2, 600, 1400, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合，以「影依猎鹰」以外的自己墓地1只「影依」怪兽为对象才能发动。那只怪兽里侧守备表示特殊召唤。 ②：这张卡被效果送去墓地的场合才能发动。这张卡里侧守备表示特殊召唤。'),
(44394295, 'Shaddoll Fusion', '影依结合', '影依融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的手卡·场上的怪兽作为融合素材，把1只「影依」融合怪兽融合召唤。从额外卡组特殊召唤的怪兽在对方场上存在的场合，自己卡组的怪兽也能作为融合素材。'),
(4939890, 'Shaddoll Hedgehog', '影依・刺猬', 'シャドール・ヘッジホッグ', 'Flip Effect Monster', 'Spellcaster', 'DARK', 3, 800, 200, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合才能发动。从卡组把1张「影依」魔法·陷阱卡加入手卡。 ②：这张卡被效果送去墓地的场合才能发动。从卡组把「影依刺猬」以外的1只「影依」怪兽加入手卡。'),
(52551211, 'Shaddoll Hound', '影依・猎犬', 'シャドール・ハウンド', 'Flip Effect Monster', 'Spellcaster', 'DARK', 4, 1600, 900, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合，以自己墓地1张「影依」卡为对象才能发动。那张卡加入手卡。 ②：这张卡被效果送去墓地的场合，以场上1只怪兽为对象才能发动。那只怪兽的表示形式变更。这个时候，「影依」怪兽以外的反转怪兽的效果不发动。'),
(21011044, 'Shaddoll Schism', '影依的伪典', '影依の偽典', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的主要阶段才能发动。自己的场上·墓地的怪兽作为融合素材除外，把1只「影依」融合怪兽融合召唤。那之后，可以把属性和这个效果特殊召唤的怪兽相同的对方场上1只怪兽送去墓地。这个效果特殊召唤的怪兽不能直接攻击。'),
(30328508, 'Shaddoll Squamata', '影依・蜥蜴', 'シャドール・リザード', 'Flip Effect Monster', 'Spellcaster', 'DARK', 4, 1800, 1000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合，以场上1只怪兽为对象才能发动。那只怪兽破坏。 ②：这张卡被效果送去墓地的场合才能发动。从卡组把「影依蜥蜴」以外的1张「影依」卡送去墓地。'),
(95401059, 'Shaddoll Zefracore', '羁绊影依－源质原核', 'オルシャドール－セフィラルーツ', 'Pendulum Effect Monster', 'Rock', 'DARK', 4, 450, 1950, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡灵摆召唤成功的场合或者这张卡被送去墓地的场合，以「绊影依-神数原核」以外的自己的灵摆区域1张「神数」卡为对象才能发动。那张卡特殊召唤。'),
(58016954, 'Shaddoll Zefranaga', '救赎影依－源质那迦', 'イェシャドール－セフィラナーガ', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 2, 900, 100, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡灵摆召唤成功的场合或者这张卡被送去墓地的场合，以自己或者对方的灵摆区域1张卡为对象才能发动。那张卡回到持有者手卡。这个效果在自己的灵摆区域有「神数」卡存在的场合才能发动和处理。'),
(57827484, 'Shadow Delver', '暗影潜伏者', 'シャドウ・ダイバー', 'Gemini Monster', 'Fiend', 'DARK', 4, 1500, 500, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当通常召唤使用的再度召唤，这张卡当作效果怪兽使用并得到以下效果。 ●选择自己场上表侧表示存在的1只暗属性·4星以下怪兽发动。选择怪兽这个回合可以直接攻击对方玩家。这个效果1回合只能使用1次。'),
(30778711, 'Shadow Ghoul', '影之食尸鬼', 'シャドウ・グール', 'Effect Monster', 'Zombie', 'DARK', 5, 1600, 1300, '自己的墓地每存在1只怪兽，这张卡的攻击力上升100。'),
(62411811, 'Shadow Ghoul of the Labyrinth', '潜伏于迷宫的影之食尸鬼', '迷宮に潜むシャドウ・グール', 'Effect Monster', 'Zombie', 'DARK', 5, 1600, 1300, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。从卡组把1张「迷宫壁」卡加入手卡。 ②：对方怪兽进行战斗的伤害步骤开始时，自己场上有「迷宫壁」卡存在的场合，把墓地的这张卡除外才能发动。那只对方怪兽破坏。'),
(35329581, 'Shadow Impulse', '暗影脉冲', 'シャドー・インパルス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「暗影脉冲」在1回合只能发动1张。 ①：自己场上的同调怪兽被战斗·效果破坏送去墓地时，以那1只怪兽为对象才能发动。和那只怪兽相同等级·种族而卡名不同的1只同调怪兽从额外卡组特殊召唤。'),
(58621589, 'Shadow of Eyes', '诱惑之影', '誘惑のシャドウ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上有怪兽被盖放时才能发动。那1只盖放的怪兽变成表侧攻击表示。（这个时候，反转效果怪兽的效果不发动。）'),
(1828513, 'Shadow of the Six Samurai - Shien', '六武众之影－紫炎', '六武衆の影－紫炎', 'XYZ Monster', 'Warrior', 'EARTH', 4, 2500, 400, '4星「六武众」怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以自己场上1只攻击力未满2000的「六武众」怪兽为对象才能发动。那只怪兽的原本攻击力直到回合结束时变成2000。这个效果在对方回合也能发动。'),
(300205003, 'Shadow Reborn', NULL, NULL, 'Skill Card', 'Yami Marik', NULL, NULL, NULL, NULL, NULL),
(57232301, 'Shadow Severing Strike', '断影烈破', '断影烈破', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：为让怪兽的效果发动而让手卡·场上的卡被表侧除外的场合才能发动。从除外的卡种类对应的以下让1个适用。 ●怪兽：场上1张表侧表示的魔法·陷阱卡的效果直到回合结束时无效。 ●魔法：自己抽2张。 ●陷阱：场上1只怪兽除外。 ②：这张卡为让怪兽的效果发动而被除外的场合才能发动。自己的除外状态的1张其他卡加入手卡。'),
(40575313, 'Shadow Specter', '地狱亡灵', 'ヘルバウンド', 'Normal Monster', 'Zombie', 'DARK', 1, 500, 200, '出现在荒野的野兽亡灵。数量多了也很棘手。'),
(29267084, 'Shadow Spell', '暗之咒缚', '闇の呪縛', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '以对方场上1只表侧表示怪兽为对象才能把这张卡发动。 ①：作为对象的怪兽的攻击力下降700，不能攻击，也不能作表示形式的变更。那只怪兽从场上离开时这张卡破坏。'),
(37620434, 'Shadow Tamer', '恶魔驯服者', 'デーモン・テイマー', 'Flip Effect Monster', 'Warrior', 'EARTH', 3, 800, 700, '反转：在回合结束前得到对方场上的1只表侧表示存在的恶魔族怪兽。'),
(6958551, 'Shadow Toon', '影子卡通', 'シャドー・トゥーン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「影子卡通」在1回合只能发动1张。 ①：自己场上有「卡通世界」存在的场合，以对方场上1只表侧表示怪兽为对象才能发动。给与对方那只表侧表示怪兽的攻击力数值的伤害。'),
(31969219, 'Shadow Trouble', '影之灾厄', '影の災い', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1张表侧表示卡为对象才能发动。卡名和那张卡相同的对方墓地的卡数量的以下效果适用。 ●1张：作为对象的卡破坏。 ●2张：作为对象的卡除外。 ●3张以上：作为对象的卡以及那些同名卡从对方的场上·墓地全部里侧除外。'),
(14212201, 'Shadow Vampire', '影子吸血鬼', 'シャドウ・ヴァンパイア', 'Effect Monster', 'Zombie', 'DARK', 5, 2000, NULL, '把这张卡作为超量召唤的素材的场合，不是暗属性怪兽的超量召唤不能使用。 ①：这张卡召唤成功时才能发动。从手卡·卡组把「影之吸血鬼」以外的1只暗属性「吸血鬼」怪兽特殊召唤。这个效果特殊召唤成功的回合，那只怪兽以外的自己怪兽不能攻击。'),
(99735427, 'Shadow-Imprisoning Mirror', '吸入暗阴的魔镜', '暗闇を吸い込むマジック・ミラー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，场上·墓地发动的暗属性怪兽的效果无效化。'),
(61322713, 'Shadow''s Light', '阴之光', '陰の光', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不能进行战斗阶段。 ①：以自己场上1只暗属性怪兽为对象才能发动。原本的种族·等级和那只怪兽相同的1只光属性怪兽从卡组·额外卡组特殊召唤。 ②：把墓地的这张卡除外才能发动。这个回合自己在通常召唤外加上只有1次，自己主要阶段可以把1只光·暗属性怪兽召唤。'),
(9603356, 'Shadowknight Archfiend', '暗影骑士恶魔', 'シャドウナイトデーモン', 'Effect Monster', 'Fiend', 'WIND', 4, 2000, 1600, '这张卡的控制者在自己的每1个准备阶段支付900基本分。当这张卡成为对方所控制的卡的效果对象时，在效果处理时掷1次骰子，若掷出3，则使此效果无效并将其破坏。这张卡对对方玩家造成的战斗伤害减半。'),
(27869883, 'Shadowpriestess of Ohm', '圣音女祭司', 'プリーステス・オーム', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1700, 1600, '可以把自己场上表侧表示存在的1只暗属性怪兽作为祭品，给与对方基本分800分伤害。'),
(20939559, 'Shadowslayer', '暗之住人 暗影杀手', '闇の住人 シャドウキラー', 'Effect Monster', 'Fiend', 'DARK', 4, 1400, 200, '对方的怪兽卡区域只有守备表示怪兽的场合，这张卡可以直接攻击对方玩家。'),
(78936551, 'Shafu, the Wheeled Mayakashi', '辙之魔妖－伡夫', '轍の魔妖－俥夫', 'Effect Monster', 'Zombie', 'EARTH', 3, 1200, 400, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以「辙之魔妖-车夫」以外的自己墓地1只「魔妖」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：只要这张卡在怪兽区域存在，自己不是「魔妖」怪兽不能从额外卡组特殊召唤。'),
(35151572, 'Shaman of the Ashened City', '灰灭之都的咒术师', '灰滅せし都の呪術師', 'Effect Monster', 'Pyro', 'DARK', 4, 1300, 1200, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：场地区域有「灰灭之都 奥布西地暮」存在的场合，这张卡可以从手卡特殊召唤。 ②：以自己的墓地·除外状态的3只炎族怪兽为对象才能发动。那些怪兽回到卡组。这个效果让「灰灭」怪兽回去的场合，可以再从卡组把1张「灰灭之都 奥布西地暮」加入手卡。'),
(78917791, 'Shaman of the Tenyi', '天威之龙仙女', '天威の龍仙女', 'Link Monster', 'Wyrm', 'FIRE', NULL, 1600, NULL, '幻龙族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：丢弃1张手卡，以自己墓地1只幻龙族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不能把「天威」怪兽以外的从额外卡组特殊召唤的场上的怪兽的效果发动。 ②：效果怪兽以外的自己的表侧表示怪兽进行战斗的攻击宣言时，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(46057733, 'Shamisen Samsara Sorrowcat', '燐回的三弦猫', '燐廻の三弦猫', 'Synchro Tuner Monster', 'Zombie', 'DARK', 3, 1600, 1200, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：对方主要阶段才能发动。用包含这张卡的自己场上的怪兽为素材进行同调召唤。 ②：这张卡在墓地存在的场合，以自己墓地1只其他的同调怪兽为对象才能发动。那只怪兽回到额外卡组，这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(92099232, 'Shapesister', '变形妖姐', 'シェイプシスター', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡发动后变成通常怪兽（恶魔族·调整·地·2星·攻/守0）在怪兽区域特殊召唤。这张卡也当作陷阱卡使用。'),
(4035199, 'Shapesnatch', '形体抓取者', 'シェイプ・スナッチ', 'Normal Monster', 'Machine', 'DARK', 5, 1200, 1700, '具有令人惊讶的力量的蝶形领带，能够套上敌人的身体，对它进行袭击。'),
(33904024, 'Shard of Greed', '强欲之碎片', '強欲なカケラ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，每次自己抽卡阶段通常抽卡，给这张卡放置1个强欲指示物。 ②：把有强欲指示物2个以上放置的这张卡送去墓地才能发动。自己从卡组抽2张。'),
(56830749, 'Share the Pain', '分担痛苦', '痛み分け', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只怪兽解放发动。对方必须把1只怪兽解放。'),
(1372887, 'Shared Ride', '同乘', '相乗り', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这个回合，每次对方用抽卡以外的方法从卡组·墓地把卡加入手卡，自己从卡组抽1张。'),
(14306092, 'Shark Caesar', '牙鲛帝 鲨皇', '牙鮫帝シャーク・カイゼル', 'XYZ Monster', 'Fish', 'WATER', 3, 1800, 2000, '3星怪兽×3只以上（最多5只） 1回合1次，把这张卡1个超量素材取除才能发动。给这张卡放置1个鲨指示物。此外，这张卡进行战斗的伤害步骤内，这张卡的攻击力上升这张卡放置的鲨指示物数量×1000的数值。'),
(20358953, 'Shark Cruiser', '巡洋鲨', 'シャーク・ザ・クルー', 'Effect Monster', 'Fish', 'WATER', 5, 1800, 2200, '自己场上表侧表示存在的这张卡被对方的卡的效果破坏的场合，可以从自己卡组把最多2只4星以下的水属性怪兽在自己场上特殊召唤。'),
(50449881, 'Shark Fortress', '鲨鱼要塞', 'シャーク・フォートレス', 'XYZ Monster', 'Fish', 'DARK', 5, 2400, 1800, '5星怪兽×2 ①：只要这张卡在怪兽区域存在，对方不能选择其他怪兽作为攻击对象。 ②：1回合1次，把这张卡1个超量素材取除，以自己场上1只表侧表示怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作2次攻击。'),
(20838380, 'Shark Stickers', '粘鲨印鱼', 'シャーク・サッカー', 'Effect Monster', 'Fish', 'WATER', 3, 200, 1000, '自己场上有鱼族·海龙族·水族怪兽召唤·特殊召唤时，这张卡可以从手卡特殊召唤。这张卡不能作为同调素材。'),
(71923655, 'Sharkraken', '触腕鲨', 'シャークラーケン', 'Effect Monster', 'Fish', 'WATER', 6, 2400, 2100, '这张卡可以把自己场上1只水属性怪兽解放，从手卡特殊召唤。'),
(75728539, 'Sharv Sarga', '新世坏回', '新世廻', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：场上有「维萨斯-斯塔弗罗斯特」存在的场合，以场上1只效果怪兽为对象才能发动。那只效果怪兽回到卡组。这个回合的结束阶段，那个持有者可以把和回去的怪兽是种族不同并是等级比那个等级·阶级·连接低的1只怪兽从卡组加入手卡。 ②：这张卡在墓地存在的状态，「吠陀」怪兽特殊召唤的场合才能发动。这张卡加入手卡。'),
(5574510, 'Shateki', '射敌', '射敵', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：丢弃1张手卡，以对方场上1只持有等级的怪兽为对象才能发动。掷1次骰子，出现的数目的以下效果适用。 ●比作为对象的怪兽的等级大的场合：作为对象的怪兽破坏。那之后，可以把原本等级和那只怪兽相同的1只怪兽从卡组加入手卡。这个回合，自己不能把「射敌」的①的效果发动。 ●作为对象的怪兽的等级以下的场合：作为对象的怪兽的等级下降1星。'),
(12117532, 'Shattered Axe', '逐渐罅裂之斧', '罅割れゆく斧', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '以场上1只表侧表示怪兽为对象才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，作为对象的怪兽的攻击力在每次自己准备阶段下降500。那只怪兽破坏时这张卡破坏。'),
(73915052, 'Sheep Token', '替罪山羊', 'スケープ・ゴート', 'Token', 'Beast', NULL, NULL, NULL, NULL, NULL),
(10163855, 'Shell Knight', '贝壳骑士', 'シェル・ナイト', 'Effect Monster', 'Rock', 'EARTH', 4, NULL, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。这张卡变成守备表示，给与对方500伤害。 ②：这张卡被效果送去墓地的场合或者被战斗破坏的场合才能发动。从卡组把1只岩石族·8星怪兽加入手卡。自己墓地有「化石融合」存在的场合，也能不加入手卡特殊召唤。这个回合，自己不能把那张卡以及那些同名卡的效果发动。'),
(77312273, 'Shell of Chaos', '混沌壳', '混沌殻', 'Effect Monster', 'Machine', 'DARK', 4, 1600, NULL, '这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地把1只光属性怪兽除外才能发动。这张卡从手卡特殊召唤。这个回合，自己不是光·暗属性的同调怪兽不能从额外卡组特殊召唤。 ②：这张卡特殊召唤成功的场合，以除外的1只自己的「混沌核」为对象才能发动。那只怪兽特殊召唤。 ③：表侧表示的这张卡从场上离开的场合除外。'),
(5087128, 'Shelrokket Dragon', '霰弹枪弹龙', 'シェルヴァレット・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 2, 1100, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：场上的这张卡为对象的连接怪兽的效果发动时才能发动。这张卡破坏。那之后，选和这张卡存在过的区域相同纵列1只怪兽破坏，那些相邻区域有怪兽存在的场合，那些也破坏。 ②：场上的这张卡被战斗·效果破坏送去墓地的回合的结束阶段才能发动。从卡组把「霰弹弹丸龙」以外的1只「弹丸」怪兽特殊召唤。'),
(27416701, 'Shiba-Warrior Taro', '柴战士 太郎', '柴戦士タロ', 'Tuner Monster', 'Beast-Warrior', 'EARTH', 2, 800, 600, '这张卡不会被战斗破坏。场上存在的卡被战斗或者卡的效果破坏时，自己场上表侧表示存在的这张卡回到持有者手卡。'),
(11035075, 'Shichi-Go-San', '死地误算守护', '死地誤算守護', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己或对方的墓地1只1星或1阶的怪兽在自己场上特殊召唤，把这张卡装备。 ②：自己·对方的结束阶段发动。装备怪兽的等级·阶级上升1。 ③：装备怪兽的等级·阶级的以下效果适用。 ●3以上：那只怪兽的攻击力上升那个原本攻击力数值。 ●5以上：那只怪兽不受对方发动的效果影响。 ④：自己准备阶段，装备怪兽的等级·阶级是7以上的场合发动。场上的卡全部送去墓地。'),
(52097679, 'Shield & Sword', '右手持盾左手持剑', '右手に盾を左手に剣を', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡的发动时场上表侧表示存在的全部怪兽的原本攻击力与原本守备力直到结束阶段时交换。'),
(30683373, 'Shield Crush', '盾碎', 'シールドクラッシュ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只守备表示怪兽为对象才能发动。那只守备表示怪兽破坏。'),
(93655221, 'Shield Handler', '屏蔽盾处理器', 'シールド・ハンドラ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：要让场上的怪兽破坏的魔法·陷阱·怪兽的效果发动时，以自己以及对方场上的连接怪兽各1只为对象才能把这张卡发动。作为对象的对方怪兽的效果无效，把这张卡当作装备卡使用给作为对象的自己怪兽装备。装备怪兽不会被效果破坏。'),
(1164211, 'Shield of the Millennium Dynasty', '仟年王朝之盾', '千年王朝の盾', 'Effect Monster', 'Warrior', 'EARTH', 5, NULL, 3000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合才能发动。这张卡当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：这张卡是当作永续魔法卡使用的场合，支付2000基本分或把手卡1张「千年十字」给对方观看才能发动。这张卡特殊召唤。那之后，可以从卡组把1张「千年十字」加入手卡。 ③：这张卡只要在怪兽区域存在，不会被魔法·陷阱卡的效果破坏。'),
(3244563, 'Shield Spear', '盾矛', 'シールドスピア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时上升400。'),
(95360850, 'Shield Warrior', '护盾战士', 'シールド・ウォリアー', 'Effect Monster', 'Warrior', 'EARTH', 3, 800, 1600, '战斗伤害计算时，把自己墓地存在的这张卡从游戏中除外才能发动。自己场上存在的怪兽不会被那次战斗破坏。'),
(28859794, 'Shield Wing', '盾翼怪鸟', 'シールド・ウィング', 'Effect Monster', 'Winged Beast', 'WIND', 2, NULL, 900, '这张卡1回合最多2次不会被战斗破坏。'),
(15939448, 'Shield Worm', '盾虫', 'シールド・ワーム', 'Effect Monster', 'Insect', 'EARTH', 4, 800, 2000, '这张卡召唤·反转召唤·特殊召唤成功时，变成守备表示。再把自己场上表侧表示存在的昆虫族怪兽数量的卡从对方卡组上面送去墓地。'),
(98126725, 'Shien''s Advisor', '紫炎的参谋', '紫炎の参謀', 'Effect Monster', 'Warrior', 'EARTH', 4, 1200, 400, '自己场上有名字带有「六武众」的怪兽表侧表示存在的场合这张卡召唤成功时，宣言1个种族发动。只要这张卡在场上表侧表示存在，宣言的种族的怪兽不能攻击宣言，双方玩家不能把宣言的种族的怪兽特殊召唤。'),
(11102908, 'Shien''s Castle of Mist', '紫炎的霞城', '紫炎の霞城', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '名字带有「六武众」的怪兽被攻击时，攻击怪兽的攻击力下降500。'),
(98162021, 'Shien''s Daredevil', '紫炎的荒武者', '紫炎の荒武者', 'Effect Monster', 'Warrior', 'EARTH', 4, 1600, 1000, '这张卡召唤成功时，给这张卡放置1个武士道指示物（最多1个）。这张卡有武士道指示物放置的场合，这张卡的攻击力上升300。此外，1回合1次，可以把这张卡放置的武士道指示物取除，并选择场上表侧表示存在的1张可以放置武士道指示物的卡放置1个武士道指示物。'),
(47436247, 'Shien''s Dojo', '紫炎之道场', '紫炎の道場', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：每次「六武众」怪兽召唤·特殊召唤，给这张卡放置1个武士道指示物。 ②：把有武士道指示物放置的这张卡送去墓地才能发动。把持有这张卡放置的武士道指示物数量以下的等级的1只「六武众」效果怪兽或者「紫炎」效果怪兽从卡组特殊召唤。'),
(99675356, 'Shien''s Footsoldier', '紫炎的足轻', '紫炎の足軽', 'Effect Monster', 'Warrior', 'EARTH', 2, 700, 300, '这张卡被战斗破坏送去墓地时，可以从卡组把1只3星以下的名字带有「六武众」的怪兽特殊召唤。'),
(77847678, 'Shien''s Scheme', '紫炎的计略', '紫炎の計略', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的名字带有「六武众」的怪兽被战斗破坏的场合才能发动。从手卡把名字带有「六武众」的怪兽最多2只特殊召唤。'),
(54031490, 'Shien''s Smoke Signal', '紫炎之狼烟', '紫炎の狼煙', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只3星以下的「六武众」怪兽加入手卡。'),
(7672244, 'Shien''s Spy', '紫炎的间者', 'シエンの間者', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只怪兽发动。直到这个回合的结束阶段时，选择的卡的控制权移给对方。'),
(33883834, 'Shien''s Squire', '紫炎的寄子', '紫炎の寄子', 'Tuner Monster', 'Warrior', 'EARTH', 1, 300, 700, '自己场上存在的名字带有「六武众」的怪兽进行战斗的场合，那次伤害计算时把这张卡从手卡送去墓地发动。那只怪兽在这个回合不会被战斗破坏。'),
(73421698, 'Shif, Fairy of the Ghoti', '游魊之妖精 西弗', 'ゴーティスの妖精シフ', 'Tuner Monster', 'Fish', 'WATER', 2, NULL, 500, '这个卡名的①②③的效果1回合各能使用1次。 ①：把墓地的这张卡除外，以自己场上1只鱼族怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升500。 ②：这张卡被除外的下个回合的准备阶段才能发动。除外状态的这张卡特殊召唤。 ③：这张卡特殊召唤的对方回合的主要阶段才能发动。用包含这张卡的自己场上的怪兽为素材进行1只鱼族同调怪兽的同调召唤。'),
(59560625, 'Shift', '换位', 'シフトチェンジ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的怪兽1只成为对方的魔法·陷阱卡的效果的对象时或者成为对方怪兽的攻击对象时才能发动。那个对象转移为自己场上1只作为正确对象的其他怪兽。'),
(59237154, 'Shifting Shadows', '蠕动的黑影', 'うごめく影', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '支付300基本分，自己的主要怪兽区域的里侧守备表示怪兽洗切，再以里侧守备表示重新排列。这个效果1个回合只能使用1次。'),
(12197223, 'Shiina, Twin Tempests of Celestial Thunder', '天雷之双风神 息那', '天雷ノ双風神 シーナ', 'Effect Monster', 'Dragon', 'WIND', 9, 2900, 1500, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有风属性怪兽存在，对方把魔法·陷阱·怪兽的效果发动时才能发动。这张卡从手卡特殊召唤。那之后，那个对方的效果种类的以下效果适用。 ●怪兽：「天雷之双风神 息那」以外的场上的表侧表示怪兽全部回到手卡。 ●魔法·陷阱：场上的魔法·陷阱卡全部回到手卡。 ②：这张卡1回合只有1次不会被战斗破坏。'),
(86327225, 'Shinato, King of a Higher Plane', '天界王 志那都', '天界王 シナト', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 8, 3300, 3000, '用「奇迹之方舟」特殊召唤。特殊召唤时，必须以场上或手卡中合计8颗星以上的怪兽作为祭品。这张卡战斗破坏对方守备表示的怪兽并将其送去墓地时，对方受到数值与被破坏怪兽的原本攻击力相同的伤害。'),
(60365591, 'Shinato''s Ark', '奇迹之方舟', '奇跡の方舟', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「天界王 志那都」降临所必需。特殊召唤时，必须以场上或手卡中合计8颗星以上的怪兽作为祭品。'),
(86952477, 'Shine Knight', '光辉骑士', 'シャインナイト', 'Effect Monster', 'Warrior', 'LIGHT', 3, 400, 1900, '只要这张卡在场上表侧守备表示存在，这张卡的等级变成4星。'),
(82878489, 'Shine Palace', '光之城', 'シャイン・キャッスル', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '光属性怪兽才能装备。 ①：装备怪兽的攻击力上升700。'),
(87303357, 'Shining Abyss', '光辉深渊', 'シャイン・アビス', 'Normal Monster', 'Fairy', 'LIGHT', 4, 1600, 1800, '光与暗之力兼备的怪兽。'),
(95956346, 'Shining Angel', '闪光天使', 'シャインエンジェル', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 800, '这张卡被战斗破坏送去墓地时，可以从卡组把1只攻击力1500以下的光属性怪兽表侧攻击表示特殊召唤。'),
(35906693, 'Shining Draw', '闪光抽牌', 'シャイニング・ドロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己抽卡阶段通过把通常抽卡的这张卡持续公开，那个回合的主要阶段1，可以以自己场上1只「希望皇 霍普」超量怪兽为对象，从以下效果选择1个发动。 ●从卡组·额外卡组选卡名不同的「异热同心武器」怪兽任意数量当作装备卡使用给作为对象的怪兽装备。 ●和作为对象的自己怪兽卡名不同的1只「希望皇 霍普」超量怪兽在那只怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(97170107, 'Shining Elf', '光辉精灵', 'シャインエルフ', 'XYZ Monster', 'Spellcaster', 'WIND', 2, 1600, 1000, '2星怪兽×2 对方对怪兽的召唤·特殊召唤成功时，把这张卡1个超量素材取除才能发动。那些怪兽的攻击力下降500。'),
(82085619, 'Shining Friendship', '友谊天使', 'フレンドシップ', 'Normal Monster', 'Fairy', 'LIGHT', 4, 1300, 1100, '即便在决斗中吵架，显示出友情就能和好。'),
(62829077, 'Shining Hope Road', '辉望道', '輝望道', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能用这张卡的效果以外把怪兽特殊召唤。 ①：以自己墓地3只怪兽为对象才能发动。那3只怪兽效果无效特殊召唤，只用那3只为素材把1只「霍普」超量怪兽超量召唤。'),
(49776811, 'Shining Piecephilia', '拼图友爱天使', 'ピースリア', 'Effect Monster', 'Rock', 'LIGHT', 4, 700, 2000, '①：这张卡不会被战斗破坏。 ②：这张卡和对方怪兽进行战斗的伤害步骤结束时才能发动。给这张卡放置1个拼图指示物（最多4个）。那之后，可以让这张卡的拼图指示物数量的以下效果适用。 ●1个：从卡组选1只怪兽在卡组最上面放置。 ●2个：自己从卡组抽1张。 ●3个：从卡组把1只怪兽加入手卡。 ●4个：从卡组选1张卡加入手卡。'),
(79791878, 'Shining Sarcophagus', '光之黄金柜', '光の黄金櫃', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡只要在魔法与陷阱区域存在，不会被怪兽的效果破坏。 ②：自己主要阶段才能发动。除「光之黄金柜」外的有「光之黄金柜」的卡名记述的1张卡从卡组加入手卡。 ③：对方从墓地把怪兽特殊召唤的场合，从手卡丢弃1张魔法卡，以那之内的1只为对象才能发动。那只怪兽送去墓地。'),
(89563150, 'Shining Silver Force', '白银防护罩 -银色之力-', '白銀のバリア－シルバーフォース－', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '对方把给与伤害的陷阱卡发动时才能发动。那个发动无效，那张卡和对方场上表侧表示存在的魔法·陷阱卡全部破坏。'),
(75874514, 'Shining Star Dragon', '辉煌的星之龙', '輝ける星の竜', 'Tuner Monster', 'Dragon', 'LIGHT', 4, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，对方主要阶段，以自己墓地1只龙族同调怪兽为对象才能发动。这张卡特殊召唤，作为对象的怪兽效果无效特殊召唤。那之后，可以用包含这张卡的自己场上的怪兽为素材进行1只龙族同调怪兽的同调召唤。 ②：用这张卡为同调素材把龙族同调怪兽同调召唤的场合，那只同调怪兽不会被战斗破坏。'),
(52900000, 'Shinobaron Peacock', '灵魂鸟神－彦孔雀', '霊魂鳥神－彦孔雀', 'Ritual Effect Monster', 'Winged Beast', 'WIND', 8, 3000, 2500, '「灵魂的降神」降临。这张卡不用仪式召唤不能特殊召唤。 ①：这张卡仪式召唤成功的场合才能发动。选对方场上最多3只怪兽回到持有者手卡。那之后，可以从手卡把1只4星以下的灵魂怪兽无视召唤条件特殊召唤。 ②：这张卡特殊召唤的回合的结束阶段发动。这张卡回到持有者手卡，在自己场上把2只「灵魂鸟衍生物」（鸟兽族·风·4星·攻/守1500）特殊召唤。'),
(60823690, 'Shinobaron Shade Peacock', '灵魂鸟影－彦孔雀', '霊魂鳥影－彦孔雀', 'Ritual Effect Monster', 'Winged Beast', 'WIND', 4, 2000, 1500, '「灵魂的降神」降临 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在手卡·场上存在当作「灵魂鸟神-彦孔雀」使用。 ②：把仪式召唤的这张卡解放才能发动。从卡组把1只灵魂怪兽和1张仪式魔法卡加入手卡。 ③：这张卡被除外的下个回合的准备阶段发动。除外状态的这张卡特殊召唤。 ④：这张卡特殊召唤的回合的结束阶段发动。这张卡回到手卡。'),
(25415052, 'Shinobaroness Peacock', '灵魂鸟神－姬孔雀', '霊魂鳥神－姫孔雀', 'Ritual Effect Monster', 'Winged Beast', 'WIND', 8, 2500, 3000, '「灵魂的降神」降临。这张卡不用仪式召唤不能特殊召唤。 ①：这张卡仪式召唤成功的场合才能发动。选对方场上最多3张魔法·陷阱卡回到持有者卡组。那之后，可以从卡组把1只4星以下的灵魂怪兽无视召唤条件特殊召唤。 ②：这张卡特殊召唤的回合的结束阶段发动。这张卡回到持有者手卡，在自己场上把2只「灵魂鸟衍生物」（鸟兽族·风·4星·攻/守1500）特殊召唤。'),
(33325951, 'Shinobaroness Shade Peacock', '灵魂鸟影－姬孔雀', '霊魂鳥影－姫孔雀', 'Ritual Effect Monster', 'Winged Beast', 'WIND', 4, 1500, 2000, '「灵魂的降神」降临 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在手卡·场上存在当作「灵魂鸟神-姬孔雀」使用。 ②：这张卡仪式召唤的场合才能发动。效果文本有「灵魂怪兽」记述的1张魔法·陷阱卡从卡组加入手卡。 ③：这张卡被除外的下个回合的准备阶段发动。除外状态的这张卡特殊召唤。 ④：这张卡特殊召唤的回合的结束阶段发动。这张卡回到手卡。'),
(70709488, 'Shinobi Insect Hagakuremino', '虫忍 叶隐蓑', '虫忍 ハガクレミノ', 'Link Monster', 'Insect', 'WIND', NULL, 1000, NULL, '卡名不同的怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡所连接区有怪兽存在，对方怪兽不能选择这张卡作为攻击对象。 ②：这张卡所连接区的怪兽被战斗·效果破坏的场合才能发动。从自己的手卡·墓地把1只4星以下的昆虫族怪兽特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(90020780, 'Shinobi Necro', '忍尸', 'シノビネクロ', 'Tuner Monster', 'Zombie', 'DARK', 2, 800, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡已在怪兽区域存在的状态，从自己墓地有这张卡以外的不死族怪兽特殊召唤的场合才能发动。自己从卡组抽1张。那之后，选1张手卡丢弃。 ②：墓地的这张卡为让效果发动而被除外的场合或者被效果除外的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(66815913, 'Shinobird Crane', '灵魂鸟－巫鹤', '霊魂鳥－巫鶴', 'Spirit Monster', 'Winged Beast', 'WIND', 4, 1500, 1500, '这张卡不能特殊召唤。 ①：1回合1次，这张卡在怪兽区域存在，这张卡以外的灵魂怪兽召唤·特殊召唤成功的场合才能发动。自己从卡组抽1张。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(39817919, 'Shinobird Crow', '灵魂鸟－忍鸦', '霊魂鳥－忍鴉', 'Spirit Monster', 'Winged Beast', 'WIND', 4, NULL, NULL, '这张卡不能特殊召唤。 ①：1回合1次，这张卡和对方怪兽进行战斗的从伤害步骤开始时到伤害计算前，从手卡丢弃1只灵魂怪兽才能发动。这张卡的攻击力·守备力直到战斗阶段结束时上升丢弃的怪兽的攻击力·守备力的各自数值。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(92200612, 'Shinobird Pigeon', '灵魂鸟－传鸠', '霊魂鳥－伝鳩', 'Spirit Monster', 'Winged Beast', 'WIND', 4, 1000, 1800, '这张卡不能特殊召唤。 ①：1回合1次，以这张卡以外的场上1只灵魂怪兽为对象才能发动。那只怪兽回到持有者手卡。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(9553721, 'Shinobird Power Spot', '灵魂鸟之据所', '霊魂の拠所', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '「灵魂的据所」的②的效果1回合只能使用1次。 ①：自己场上的灵魂怪兽的攻击力·守备力上升500。 ②：自己场上的表侧表示的风属性怪兽回到自己手卡的场合才能发动。从卡组把1只灵魂怪兽或者1张仪式魔法卡加入手卡。'),
(276357, 'Shinobird Salvation', '灵魂鸟之圆环', '霊魂の円環', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「灵魂的圆环」的①②的效果1回合各能使用1次。 ①：这张卡在魔法与陷阱区域存在，自己场上的表侧表示的灵魂怪兽回到自己手卡的场合，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：对方怪兽的攻击宣言时把自己墓地1只灵魂怪兽除外才能发动。那次攻击无效，那之后战斗阶段结束。'),
(25415053, 'Shinobird Token', '灵魂鸟神－姬孔雀', '霊魂鳥神－姫孔雀', 'Token', 'Winged Beast', NULL, NULL, NULL, NULL, NULL),
(73055622, 'Shinobird''s Calling', '灵魂鸟之降神', '霊魂の降神', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「灵魂鸟神-姬孔雀」「灵魂鸟神-彦孔雀」的降临必需。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放或者作为解放的代替而把自己墓地的灵魂怪兽除外，从手卡把「灵魂鸟神-姬孔雀」或者「灵魂鸟神-彦孔雀」仪式召唤。'),
(49131917, 'Shinonome the Vaylantz Priestess', '弈勇之巫女－东云', 'ヴァリアンツの巫女－東雲', 'Pendulum Effect Monster', 'Spellcaster', 'WATER', 2, 500, 500, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡是已特殊召唤的场合，自己主要阶段才能发动。从卡组把1张「群豪」魔法卡加入手卡。 ②：怪兽区域的这张卡向其他的怪兽区域移动的场合才能发动。从卡组把「群豪之巫女-东云」以外的1只「群豪」怪兽加入手卡。'),
(94081496, 'Shiny Black "C"', '黑亮的G', '黒光りするG', 'Effect Monster', 'Insect', 'EARTH', 1, 200, 500, '对方场上有1只同调怪兽特殊召唤时，把自己墓地存在的这张卡从游戏中除外发动。那1只同调怪兽破坏。'),
(4148264, 'Shiny Black "C" Squadder', 'Z战队 耀黑', 'G戦隊 シャインブラック', 'Normal Monster', 'Insect', 'EARTH', 4, 2000, NULL, '身穿黑亮战衣并游走战场的“黑之闪光”…。哪里有暗影哪里就有G战队！它们还会运用自己暗藏的飞行能力来对付巨大怪兽呢！！'),
(101303088, 'Shipping Archfiend', NULL, NULL, 'Tuner Monster', 'Fiend', 'WIND', 3, NULL, NULL, NULL),
(58761791, 'Shipping Error', '误出货', '誤出荷', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：包含从卡组把卡加入手卡效果的魔法·陷阱·怪兽的效果发动时才能发动。那个效果变成「对方从自身卡组选1张卡。自己把那张卡加入手卡。自己把这个效果加入手卡的卡持续公开，这个回合的结束阶段，公开中的那张卡回到原本持有者的卡组，自己抽1张。」。'),
(35818851, 'Shiranui Samurai', '不知火的武士', '不知火の武士', 'Effect Monster', 'Zombie', 'FIRE', 4, 1800, NULL, '「不知火的武士」的①②的效果1回合各能使用1次。 ①：把自己墓地1只不死族怪兽除外才能发动。这张卡的攻击力直到回合结束时上升600，这个回合这张卡和怪兽进行战斗的场合，那只怪兽在伤害计算后除外。这个效果在对方回合也能发动。 ②：这张卡被除外的场合，以「不知火的武士」以外的自己墓地1只「不知火」怪兽为对象才能发动。那只怪兽加入手卡。'),
(57288064, 'Shiranui Samuraisaga', '刀神－不知火', '刀神－不知火', 'Synchro Monster', 'Zombie', 'FIRE', 6, 2500, NULL, '不死族调整＋调整以外的不死族怪兽1只以上 自己对「刀神-不知火」1回合只能有1次特殊召唤。 ①：1回合1次，以除外的1只自己的不死族怪兽为对象才能发动。那只怪兽回到卡组，持有那个攻击力以下的攻击力的对方场上的怪兽全部变成守备表示。这个效果在对方回合也能发动。 ②：这张卡被除外的场合，以对方场上1只怪兽为对象才能发动。那只怪兽的攻击力下降500。'),
(83283063, 'Shiranui Shogunsaga', '战神－不知火', '戦神－不知火', 'Synchro Monster', 'Zombie', 'FIRE', 8, 3000, NULL, '不死族调整＋调整以外的不死族怪兽1只以上 自己对「战神-不知火」1回合只能有1次特殊召唤。 ①：这张卡特殊召唤成功的场合，从自己墓地把1只不死族怪兽除外才能发动。这张卡的攻击力直到回合结束时上升除外的怪兽的原本攻击力数值。 ②：场上的这张卡被战斗·效果破坏送去墓地的场合，以除外的1只自己的守备力0的不死族怪兽为对象才能发动。那只怪兽回到墓地。'),
(86926989, 'Shiranui Skillsaga Supremacy', '丽神－不知火', '麗神－不知火', 'Link Monster', 'Zombie', 'FIRE', NULL, 2300, NULL, '不死族怪兽2只以上 这个卡名的③的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己场上的同调怪兽不会被效果破坏。 ②：只要这张卡在怪兽区域存在，自己的炎属性怪兽不会被战斗破坏。 ③：对方回合，以除外的1只自己的不死族同调怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。'),
(62038047, 'Shiranui Smith', '不知火的锻师', '不知火の鍛師', 'Effect Monster', 'Zombie', 'FIRE', 4, 1000, NULL, '「不知火的锻师」的①的效果1回合只能使用1次。 ①：场上的这张卡作为同调素材送去墓地的场合才能发动。从卡组把「不知火的锻师」以外的1张「不知火」卡加入手卡。 ②：这张卡被除外的场合才能发动。这个回合，自己的不死族怪兽不会被战斗破坏。'),
(94801854, 'Shiranui Solitaire', '不知火的隐者', '不知火の隠者', 'Effect Monster', 'Zombie', 'FIRE', 4, 500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只不死族怪兽解放才能发动。从卡组把1只守备力0的不死族调整特殊召唤。 ②：这张卡被除外的场合，以「不知火的隐者」以外的除外的1只自己的「不知火」怪兽为对象才能发动。那只怪兽特殊召唤。场上有「不知火流 转生之阵」存在的场合，这个效果的对象可以变成2只。'),
(36630403, 'Shiranui Spectralsword', '妖刀－不知火', '妖刀－不知火', 'Tuner Monster', 'Zombie', 'FIRE', 2, 800, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡在墓地存在的场合，以调整以外的自己墓地1只不死族怪兽为对象才能发动。那只怪兽和这张卡从墓地除外，把持有和那2只的等级合计相同等级的1只不死族同调怪兽从额外卡组特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(79783880, 'Shiranui Spectralsword Shade', '逢魔之妖刀－不知火', '逢魔ノ妖刀－不知火', 'Tuner Monster', 'Zombie', 'FIRE', 3, 800, NULL, '这个卡名的效果1回合只能使用1次。 ①：把这张卡解放，从「逢魔之妖刀-不知火」以外的除外的自己怪兽之中以包含「不知火」怪兽的2只不死族怪兽为对象才能发动。那些怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果的发动后，直到回合结束时自己不是不死族怪兽不能特殊召唤。'),
(99423156, 'Shiranui Spiritmaster', '不知火的宫司', '不知火の宮司', 'Effect Monster', 'Zombie', 'FIRE', 4, 1500, NULL, '「不知火的宫司」的②的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。从自己的手卡·墓地选「不知火的宫司」以外的1只「不知火」怪兽特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。 ②：这张卡被除外的场合，以对方场上1张表侧表示的卡为对象才能发动。那张卡破坏。'),
(41562624, 'Shiranui Squire', '不知火的武部', '不知火の武部', 'Effect Monster', 'Zombie', 'FIRE', 4, 1500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时才能发动。从手卡·卡组把1只「妖刀-不知火」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是不死族怪兽不能特殊召唤。 ②：这张卡被除外的场合才能发动。自己从卡组抽1张。那之后，选1张手卡丢弃。'),
(52711246, 'Shiranui Squiresaga', '妖神－不知火', '妖神－不知火', 'Synchro Monster', 'Zombie', 'FIRE', 7, 2100, NULL, '调整＋调整以外的怪兽1只以上 自己对「妖神-不知火」1回合只能有1次特殊召唤。 ①：1回合1次，自己主要阶段才能发动。从自己墓地以及自己场上的表侧表示怪兽之中选1只怪兽除外。那之后，那种类对应的以下效果各能适用。 ●不死族：自己场上的全部怪兽的攻击力上升300。 ●炎属性：选场上1张魔法·陷阱卡破坏。 ●同调：选场上1只怪兽破坏。'),
(78765160, 'Shiranui Style Samsara', '不知火流 轮回之阵', '不知火流 輪廻の陣', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡只要在魔法与陷阱区域存在，卡名当作「不知火流 转生之阵」使用。 ②：1回合1次，可以从以下效果选择1个发动。 ●把自己场上1只表侧表示的不死族怪兽除外才能发动。这个回合，自己受到的全部伤害变成0。 ●以除外的2只自己的守备力0的不死族怪兽为对象才能发动。那2只怪兽回到卡组洗切。那之后，自己从卡组抽1张。'),
(40364916, 'Shiranui Style Solemnity', '不知火流 传承之阵', '不知火流 伝承の陣', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡只要在魔法与陷阱区域存在，卡名当作「不知火流 转生之阵」使用。 ②：1回合1次，可以从以下效果选择1个发动。 ●从自己墓地把1只不死族怪兽除外才能发动。这个回合，自己的不死族怪兽的召唤·特殊召唤不会被无效化。 ●以自己场上1只不死族怪兽为对象才能发动。那只怪兽除外。那之后，可以从卡组把1只守备力0的不死族怪兽送去墓地。'),
(74798297, 'Shiranui Style Success', '不知火流 才华之阵', '不知火流 才華の陣', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从手卡把1只不死族怪兽特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。 ②：把墓地的这张卡除外，以自己场上1只不死族怪兽为对象才能发动。这个回合，那只不死族怪兽不受自身以外的卡的效果影响。'),
(4333086, 'Shiranui Style Swallow''s Slash', '不知火流 燕之太刀', '不知火流 燕の太刀', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只不死族怪兽解放，以场上2张卡为对象才能发动。那些卡破坏。那之后，从卡组把1只「不知火」怪兽除外。'),
(40005099, 'Shiranui Style Synthesis', '不知火流 转生之阵', '不知火流 転生の陣', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '「不知火流 转生之阵」在1回合只能发动1张。 ①：1回合1次，自己场上没有怪兽存在的场合，可以把1张手卡送去墓地，从以下效果选择1个发动。 ●以自己墓地1只守备力0的不死族怪兽为对象才能发动。那只怪兽特殊召唤。 ●以除外的1只自己的守备力0的不死族怪兽为对象才能发动。那只怪兽回到墓地。'),
(59843383, 'Shiranui Sunsaga', '炎神－不知火', '炎神－不知火', 'Synchro Monster', 'Zombie', 'FIRE', 10, 3500, NULL, '不死族调整＋调整以外的不死族怪兽1只以上 自己对「炎神-不知火」1回合只能有1次特殊召唤。 ①：这张卡特殊召唤成功的场合才能发动。从自己墓地的卡以及除外的自己的卡之中选不死族同调怪兽任意数量回到额外卡组。那之后，可以选回去数量的对方场上的卡破坏。 ②：自己场上的不死族怪兽被战斗·效果破坏的场合，可以作为代替把自己墓地1只「不知火」怪兽除外。'),
(5177985, 'Shiranui Swordmaster', '不知火的师范', '不知火の師範', 'Effect Monster', 'Zombie', 'FIRE', 2, 600, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在墓地存在，自己场上有「不知火」怪兽2种类以上存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡被除外的场合，以自己场上1只不死族怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升600。'),
(26326541, 'Shiranui Swordsaga', '业神－不知火', '業神－不知火', 'Synchro Monster', 'Zombie', 'FIRE', 5, 1900, NULL, '调整＋调整以外的怪兽1只以上 自己对「业神-不知火」1回合只能有1次特殊召唤，那个②的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合，以场上1只怪兽为对象才能发动。那只怪兽的表示形式变更。 ②：这张卡被除外的场合才能发动。在自己场上把1只「不知火衍生物」（不死族·炎·1星·攻/守0）特殊召唤。'),
(2420921, 'Shire, Lightsworn Spirit', '光道圣灵 夏尔', 'ライトロード・スピリット シャイア', 'Effect Monster', 'Fairy', 'LIGHT', 3, 400, 1400, '墓地中每有1种名字带有「光道」的怪兽卡，这张卡的攻击力就上升300。每次自己的结束阶段时，将自己卡组最上方的2张卡送去墓地。'),
(15609017, 'Shock Surprise', '隐蔽射击', 'ヒドゥン・ショット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己墓地最多2只「疾行机人」怪兽除外，以除外数量的场上的卡为对象才能发动。那些卡破坏。'),
(38528901, 'Shock Troops of the Ice Barrier', '冰结界的决起队', '氷結界の決起隊', 'Effect Monster', 'Spellcaster', 'WATER', 3, 1500, 800, '①：把这张卡解放，以场上1只水属性怪兽为对象才能发动。那只水属性怪兽破坏，从卡组把1只「冰结界」怪兽加入手卡。'),
(2584136, 'Shocktopus', '章鲛', 'シャクトパス', 'Effect Monster', 'Fish', 'WATER', 4, 1600, 800, '这张卡被和对方怪兽的战斗破坏送去墓地时，可以把这张卡当作装备卡使用给那只对方怪兽装备。用这个效果把这张卡装备的怪兽攻击力变成0，不能把表示形式变更。'),
(41493640, 'Shogi Knight', '行列怪兽 骑士之桂马', 'ラインモンスター Kホース', 'Effect Monster', 'Beast-Warrior', 'EARTH', 3, 800, 400, '这张卡召唤成功时，选择对方的魔法与陷阱卡区域盖放的1张卡才能发动。把盖放的那张卡确认，陷阱卡的场合，那张卡破坏。不是的场合，回到原状。这个效果把陷阱卡破坏时，可以把以下效果发动。 ●从手卡把1只地属性·3星怪兽表侧守备表示特殊召唤。'),
(32476434, 'Shogi Lance', '行列怪兽 枪之香车', 'ラインモンスター スピア・ホイール', 'Effect Monster', 'Beast-Warrior', 'EARTH', 3, 500, 500, '1回合1次，选择这张卡以外的自己场上1只兽战士族·3星怪兽才能发动。选择的怪兽和这张卡变成各自等级合计的等级。'),
(40939228, 'Shooting Majestic Star Dragon', '流天救世星龙', 'シューティング・セイヴァー・スター・ドラゴン', 'Synchro Monster', 'Dragon', 'WIND', 11, 4000, 3300, '「救世龙」＋包含龙族同调怪兽的除调整以外的怪兽1只以上 这张卡用同调召唤才能从额外卡组特殊召唤。 ①：1回合1次，可以发动。选对方场上1只效果怪兽，那个效果无效。 ②：这张卡在通常攻击外加上可以作出最多有自己墓地的「星尘龙」以及有那个卡名记述的同调怪兽数量的攻击。 ③：1回合1次，对方把效果发动时才能发动。这张卡直到结束阶段除外，那个发动无效并除外。'),
(35952884, 'Shooting Quasar Dragon', '流天类星龙', 'シューティング・クェーサー・ドラゴン', 'Synchro Monster', 'Dragon', 'LIGHT', 12, 4000, 4000, '同调怪兽调整＋调整以外的同调怪兽2只以上 这张卡不用同调召唤不能特殊召唤。 ①：这张卡在同1次的战斗阶段中可以作出最多有那些作为同调素材的怪兽之内除调整以外的怪兽数量的攻击。 ②：1回合1次，魔法·陷阱·怪兽的效果发动时才能发动。那个发动无效并破坏。 ③：表侧表示的这张卡从场上离开时才能发动。从额外卡组把1只「流星龙」特殊召唤。'),
(68431965, 'Shooting Riser Dragon', '流升龙', 'シューティング・ライザー・ドラゴン', 'Synchro Tuner Monster', 'Dragon', 'LIGHT', 7, 2100, 1700, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤的场合才能发动。把持有比场上的这张卡低的等级的1只怪兽从卡组送去墓地，这张卡的等级下降那只怪兽的等级数值。这个回合，自己不能把那只怪兽以及那些同名怪兽的怪兽效果发动。 ②：对方主要阶段才能发动（同一连锁上最多1次）。用包含这张卡的自己场上的怪兽为素材进行同调召唤。'),
(47264717, 'Shooting Star', '流星', 'シューティング・スター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上有「星尘」怪兽存在的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(95638658, 'Shooting Star Bow - Ceal', '流星之弓-烨焰', '流星の弓－シール', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备这张卡的怪兽攻击力下降1000点。装备这张卡的怪兽可以对对方进行直接攻击。'),
(24696097, 'Shooting Star Dragon', '流星龙', 'シューティング・スター・ドラゴン', 'Synchro Monster', 'Dragon', 'WIND', 10, 3300, 2500, '同调怪兽调整＋「星尘龙」 ①：1回合1次，可以发动。从自己卡组上面翻开5张并回到卡组。这个回合这张卡可以作出最多有所翻开之中的调整数量的攻击。 ②：1回合1次，要让场上的卡破坏的效果的发动时才能发动。那个效果无效并破坏。 ③：1回合1次，对方的攻击宣言时以攻击怪兽为对象才能发动。场上的这张卡除外，那次攻击无效。 ④：这个③的效果除外的回合的结束阶段发动。这张卡特殊召唤。'),
(63180841, 'Shooting Star Dragon T.G. EX', '流星龙・T.G.扩展版', 'シューティング・スター・ドラゴン・TG－EX', 'Synchro Monster', 'Dragon', 'WIND', 10, 3300, 2500, '同调怪兽调整＋调整以外的同调怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：自己场上的怪兽为对象的怪兽的效果发动时，从自己墓地把1只调整除外才能发动。那个发动无效并破坏。 ②：对方怪兽的攻击宣言时才能发动。那次攻击无效。 ③：对方回合，这张卡在墓地存在的场合，把自己场上2只同调怪兽解放才能发动。这张卡特殊召唤。'),
(33897356, 'Shootingcode Talker', '射码语者', 'シューティングコード・トーカー', 'Link Monster', 'Cyberse', 'WATER', NULL, 2300, NULL, '电子界族怪兽2只以上 ①：自己战斗阶段开始时才能发动。这次战斗阶段中，这张卡可以向对方怪兽作出最多有这张卡所连接区的怪兽数量＋1次的攻击。这个回合，对方场上的怪兽只有1只的场合，和那只怪兽进行战斗的这张卡的攻击力只在那次伤害计算时下降400。 ②：自己·对方的战斗阶段结束时才能发动。自己从卡组抽出这个回合这张卡战斗破坏的怪兽的数量。'),
(5908650, 'Shopina the Melodious Maestra', '幻奏音姬 桂冠肖邦', '幻奏の音姫ローリイット・フランソワ', 'Effect Monster', 'Fairy', 'LIGHT', 7, 2300, 1700, '这张卡的效果发动的回合，自己不能把光属性以外的怪兽的效果发动。 ①：1回合1次，以自己墓地1只天使族·光属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(14771222, 'Shore Knight', '绝海之骑士', '絶海の騎士', 'Effect Monster', 'Warrior', 'WATER', 4, 1400, 1200, '场上表侧表示存在的这张卡的表示形式变更时，从卡组把1只水属性怪兽送去墓地。这个效果1回合只能使用1次。'),
(75967082, 'Short Circuit', '漏电', '漏電', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上名字带有「电池人」的怪兽有3只以上表侧表示存在的场合才能发动。对方场上存在的卡全部破坏。'),
(71950093, 'Shovel Crusher', '铁铲粉碎机', 'シャベル・クラッシャー', 'Normal Monster', 'Machine', 'EARTH', 3, 900, 1200, '善于破坏一切。要注意其双手的大铲。'),
(92080692, 'Showdown of the Secret Sense Scroll Techniques', '看破的极意', '見切りの極意', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：和对方墓地的卡同名的怪兽的效果·魔法·陷阱卡由对方发动时才能发动。那个发动无效并破坏。'),
(3603242, 'Shreddder', '碎纸机器人', 'シュレツダー', 'Effect Monster', 'Machine', 'EARTH', 4, 1600, 1000, '从手卡把1只机械族怪兽送去墓地发动。送去墓地的怪兽的等级以下的对方场上表侧表示存在的1只怪兽破坏。这个效果1回合只能使用1次。'),
(4215636, 'Shrine of Mist Valley', '霞之谷的祭坛', '霞の谷の祭壇', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '风属性怪兽被卡的效果破坏送去自己墓地时，可以从自己的手卡·卡组把1只风属性·3星以下的怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果1回合只能使用1次。'),
(55713623, 'Shrink', '收缩', '収縮', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的原本攻击力直到回合结束时变成一半。'),
(14816688, 'Shuffle Reborn', '洗牌苏生', 'シャッフル・リボーン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上没有怪兽存在的场合，以自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段除外。 ②：把墓地的这张卡除外，以自己场上1张卡为对象才能发动。那张卡回到持有者卡组洗切，那之后自己从卡组抽1张。这个回合的结束阶段，自己1张手卡除外。'),
(32615065, 'Shura the Combat Star', '霸道星 修罗', '覇道星シュラ', 'Fusion Monster', 'Warrior', 'DARK', 12, NULL, NULL, '「霸胜星 韦驮天」＋5星以上的战士族怪兽 ①：1回合1次，自己·对方的战斗阶段才能发动。对方场上的全部表侧表示怪兽的攻击力变成0。 ②：怪兽之间进行战斗的伤害计算时才能发动1次。那些进行战斗的双方怪兽的攻击力只在那次伤害计算时上升各自等级×200。 ③：融合召唤的这张卡被对方破坏送去墓地的场合才能发动。把1只「霸胜星 韦驮天」当作融合召唤从额外卡组特殊召唤。'),
(90307777, 'Shurit, Strategist of the Nekroz', '影灵衣的术士 休里特', '影霊衣の術士 シュリット', 'Effect Monster', 'Warrior', 'WATER', 3, 300, 1800, '这个卡名的②的效果1回合只能使用1次。 ①：「影灵衣」仪式怪兽1只仪式召唤的场合，可以由这1张卡作为仪式召唤需要的等级数值的解放使用。 ②：这张卡被效果解放的场合才能发动。从卡组把1只战士族「影灵衣」仪式怪兽加入手卡。'),
(65422840, 'Shutendoji', '酒吞童子', '酒呑童子', 'Effect Monster', 'Zombie', 'EARTH', 4, 1500, 800, '①：1回合1次，可以从以下效果选择1个发动。 ●从自己墓地把2只不死族怪兽除外才能发动。自己从卡组抽1张。 ●以除外的1只自己的不死族怪兽为对象才能发动。那只怪兽回到卡组最上面。'),
(10449150, 'Shuttleroid', '航天机人', 'シャトルロイド', 'Effect Monster', 'Machine', 'WIND', 4, 1000, 1200, '这张卡被选择作为攻击对象时，可以把这张卡从游戏中除外。这个效果从游戏中除外的场合，这张卡在下次的自己的准备阶段时特殊召唤。那个时候，给与对方基本分1000分伤害。'),
(30922149, 'Side Effects?', '副作用？', '副作用？', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方从卡组抽出1～3张的任意数量。那之后，自己回复这个效果让对方抽出的数量×2000基本分。'),
(9634146, 'Signal Warrior', '信号战士', 'シグナル・ウォリアー', 'Synchro Monster', 'Warrior', 'LIGHT', 7, 2400, 1000, '调整＋调整以外的怪兽1只以上 ①：每次双方的准备阶段发动。给这张卡以及场地区域的表侧表示的卡全部各放置1个信号指示物。 ②：有信号指示物放置的这张卡不会被战斗以及对方的效果破坏。 ③：1回合1次，可以把自己·对方场上的信号指示物的以下数量取除，那个效果发动。 ●4：给与对方800伤害。 ●7：自己从卡组抽1张。 ●10：选场上1张卡破坏。'),
(85277313, 'Signs of the Tistina', '提斯蒂娜的胎动', 'ティスティナの胎動', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能把这张卡发动。发动后变成持有以下效果的效果怪兽（水族·光·10星·攻/守0）在怪兽区域特殊召唤（也当作陷阱卡使用）。 ●对方回合作为对象的表侧表示怪兽从场上离开时这张卡破坏。对方回合这张卡从场上离开时作为对象的表侧表示怪兽破坏。'),
(86442081, 'Silent Abyss', '寂静深渊', 'サイレントアビス', 'Effect Monster', 'Reptile', 'WATER', 7, 2000, 1500, '这张卡被战斗破坏送去墓地时，场上表侧表示存在的水属性怪兽以外的怪兽全部破坏。'),
(90303176, 'Silent Angler', '寂静鮟鱇', 'サイレント・アングラー', 'Effect Monster', 'Fish', 'WATER', 4, 800, 1400, '①：自己场上有水属性怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤过的回合，自己不能从手卡把怪兽特殊召唤。'),
(44968459, 'Silent Burning', '沉默魔爆破', 'サイレント・バーニング', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上有「沉默魔术师」怪兽存在，自己手卡比对方多的场合，自己·对方的战斗阶段才能发动（这张卡的发动和效果不会被无效化）。双方玩家各自直到手卡变成6张为止抽卡。 ②：自己主要阶段把墓地的这张卡除外才能发动。从卡组把1只「沉默魔术师」怪兽加入手卡。'),
(42534368, 'Silent Doom', '沉默的死者', '黙する死者', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只通常怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽不能攻击。');